<script setup lang="ts">
import {onMounted,ref} from 'vue';
const props=defineProps<{view:string}>();const data=ref<any>(null),error=ref(''),loading=ref(false);
async function api(url:string){const response=await fetch(url,{credentials:'same-origin',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.message||'Request failed');return payload}const from=ref(new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10)),to=ref(new Date().toISOString().slice(0,10));
async function load(){loading.value=true;error.value='';try{data.value=await api(`/api/analytics/overview?from=${encodeURIComponent(from.value)}&to=${encodeURIComponent(to.value)}`)}catch(e:any){error.value=e.response?.data?.message||'Analytics could not be loaded.'}finally{loading.value=false}}onMounted(load);
const money=(v:number)=>'৳'+Number(v||0).toLocaleString('en-BD',{maximumFractionDigits:2});
</script>
<template><main class="space-y-5 p-6"><header class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-xs font-semibold tracking-widest text-violet-600">BUSINESS INTELLIGENCE</p><h1 class="text-2xl font-semibold">{{view==='sales'?'Sales Analytics':view==='website'?'Website Analytics':view==='marketing'?'Marketing Analytics':'Analytics Overview'}}</h1><p class="text-sm text-slate-500">Decision-ready metrics calculated from recorded Madina Scale data.</p></div><div class="flex flex-wrap items-end gap-2"><label class="text-xs">From<input v-model="from" type="date" class="mt-1 block rounded-lg border p-2 text-sm"></label><label class="text-xs">To<input v-model="to" type="date" class="mt-1 block rounded-lg border p-2 text-sm"></label><button class="rounded-lg bg-slate-900 px-4 py-2 text-white" @click="load">Apply</button></div></header><p v-if="error" class="rounded-lg bg-red-50 p-3 text-red-700">{{error}}</p><p v-if="loading" class="text-sm text-slate-500">Loading analytics…</p><template v-if="data"><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article v-for="m in [{l:'Revenue',v:money(data.summary.revenue)},{l:'Valid Orders',v:data.summary.orders.toLocaleString()},{l:'Average Order Value',v:money(data.summary.average_order_value)},{l:'Customers (all-time)',v:data.summary.customers.toLocaleString()}]" class="rounded-xl border bg-white p-4"><p class="text-sm text-slate-500">{{m.l}}</p><strong class="mt-1 block text-2xl">{{m.v}}</strong></article></section><section class="grid gap-4 xl:grid-cols-2"><article class="rounded-xl border bg-white p-4"><h2 class="font-semibold">Daily sales</h2><p class="mb-4 text-xs text-slate-500">Recorded valid sales orders, {{data.range.from}} to {{data.range.to}}</p><div v-if="data.daily.length" class="space-y-3"><div v-for="d in data.daily" class="grid grid-cols-[90px_1fr_110px] items-center gap-2 text-sm"><span class="text-slate-500">{{d.date}}</span><div class="h-3 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full bg-blue-500" :style="{width:(Number(d.revenue)/Math.max(...data.daily.map((x:any)=>Number(x.revenue)),1)*100)+'%'}"></div></div><strong class="text-right">{{money(d.revenue)}}</strong></div></div><p v-else class="py-8 text-center text-sm text-slate-500">No sales in this date range.</p></article><article class="rounded-xl border bg-white p-4"><h2 class="font-semibold">Order status distribution</h2><div class="mt-4 space-y-3"><div v-for="s in data.order_status" class="flex items-center justify-between border-b pb-2 text-sm"><span class="capitalize">{{s.status}}</span><strong>{{s.count}}</strong></div><p v-if="!data.order_status.length" class="py-8 text-center text-sm text-slate-500">No order status data.</p></div></article></section><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article v-for="m in [{l:'Tracked campaign impressions',v:data.summary.campaign_impressions},{l:'Tracked campaign clicks',v:data.summary.campaign_clicks},{l:'Tracked campaign conversions',v:data.summary.campaign_conversions},{l:'Tracked campaign conversion value',v:money(data.summary.tracked_campaign_conversion_value)}]" class="rounded-xl border bg-white p-4"><p class="text-sm text-slate-500">{{m.l}}</p><strong class="text-xl">{{m.v}}</strong></article></section><p class="text-xs text-slate-500">Measurement note: customer count is all-time. Website visitor/session/page-view metrics are not shown until a privacy-aware web analytics event source is configured. Campaign metrics include only events explicitly recorded against campaigns; they are not inferred from sales orders.</p></template></main></template>
